import sys, time, torch, torch.nn.functional as F
from torch import nn
torch.backends.cudnn.benchmark = True
def cbr(ci, co, pool=False):
    l=[nn.Conv2d(ci,co,3,padding=1,bias=False)]
    if pool: l.append(nn.MaxPool2d(2))
    l+= [nn.BatchNorm2d(co), nn.ReLU(inplace=True)]
    return nn.Sequential(*l)
class Res(nn.Module):
    def __init__(s,c): super().__init__(); s.a=cbr(c,c); s.b=cbr(c,c)
    def forward(s,x): return x+s.b(s.a(x))
def net(w, poolfirst):
    if poolfirst:
        body=[cbr(3,w), cbr(w,2*w,True), Res(2*w), cbr(2*w,4*w,True), cbr(4*w,8*w,True), Res(8*w)]
    else:
        body=[cbr(3,w), cbr(w,2*w), nn.MaxPool2d(2), Res(2*w), cbr(2*w,4*w), nn.MaxPool2d(2), cbr(4*w,8*w), nn.MaxPool2d(2), Res(8*w)]
    return nn.Sequential(*body, nn.AdaptiveMaxPool2d(1), nn.Flatten(), nn.Linear(8*w,100,bias=False))
def bench(m, bs=512, steps=50, name='', res=32):
    m = m.cuda().to(memory_format=torch.channels_last)
    f = torch.compile(m)
    opt = torch.optim.SGD(m.parameters(), lr=0.1, momentum=0.9, nesterov=True)
    x = torch.randn(bs,3,res,res,device='cuda',dtype=torch.bfloat16).contiguous(memory_format=torch.channels_last)
    y = torch.randint(0,100,(bs,),device='cuda')
    def step():
        with torch.autocast('cuda',dtype=torch.bfloat16):
            loss = F.cross_entropy(f(x), y)
        opt.zero_grad(set_to_none=True); loss.backward(); opt.step()
    for _ in range(5): step()
    torch.cuda.synchronize(); t=time.time()
    for _ in range(steps): step()
    torch.cuda.synchronize(); dt=(time.time()-t)/steps
    print(f'{name} bs={bs} res={res}: {dt*1000:.2f} ms/step, {dt*50000/bs:.3f} s/epoch', flush=True)
bench(net(64,False), name='orig')
bench(net(64,True), name='poolfirst')
bench(net(64,True), name='poolfirst', res=24)
bench(net(64,True), name='poolfirst', res=16)
